mapper.select:
SELECT CONFIG_ID, CONFIG_NAME, CONFIG_CODE, DATA_SOURCE_TYPE, CONNECTION_URL, USERNAME, PASSWORD, DRIVER_CLASS, TABLE_NAME, SQL_QUERY, API_URL, API_METHOD, API_HEADERS, API_PARAMS, FILE_PATH, FILE_ENCODING, DELIMITER, QUOTE_CHAR, FIXED_WIDTH_CONFIG, DESCRIPTION, IS_ENABLED, IS_TESTED, TEST_TIME, TEST_RESULT, TENANT_ID, CREATE_TIME, UPDATE_TIME, CREATE_USER, UPDATE_USER FROM TBL_DATA_SOURCE_CONFIG WHERE TENANT_ID = #{tenantId}
AND CONFIG_NAME LIKE '%' || #{param.configName} || '%'
AND CONFIG_CODE LIKE '%' || #{param.configCode} || '%'
AND DATA_SOURCE_TYPE = #{param.dataSourceType}
AND IS_ENABLED = #{param.isEnabled}
ORDER BY CREATE_TIME DESC

mapper.update:
UPDATE TBL_DATA_SOURCE_CONFIG
SET IS_ENABLED = #{isEnabled},
    UPDATE_TIME = SYSDATE,
    UPDATE_USER = #{updateUser}
WHERE CONFIG_ID IN

    #{id}

